<script setup lang="ts">
import { ref, watch, onUnmounted } from 'vue'; import Button from 'primevue/button'; import InputText from 'primevue/inputtext'; import Textarea from 'primevue/textarea'; import Dialog from 'primevue/dialog'; import DataTable from 'primevue/datatable'; import Column from 'primevue/column'; import { useToast } from 'primevue/usetoast'; import { api, currentUser } from '../lib/api'; import { initials, date, type Data } from '../lib/types'; import { useQuery } from '../composables/useQuery'; import StatusBadge from '../components/StatusBadge.vue'; import QueryState from '../components/QueryState.vue';
const search=ref(''),selected=ref<Data>(),show=ref(false),reason=ref(''),busy=ref(false),toast=useToast();const {data,loading,error,refresh}=useQuery(()=>api('/admin/customers?q='+encodeURIComponent(search.value)));let timer:ReturnType<typeof setTimeout>;watch(search,()=>{clearTimeout(timer);timer=setTimeout(refresh,350);});
onUnmounted(() => clearTimeout(timer));
async function restrict(){if(!selected.value)return;busy.value=true;try{await api('/admin/users/'+selected.value.id+'/restrictions',{method:'POST',body:{expectedVersion:selected.value.version,blocked:selected.value.status==='ACTIVE',reasonCode:reason.value}});show.value=false;await refresh();toast.add({severity:'success',summary:'Đã cập nhật hạn chế tài khoản',life:3000});}catch(e){toast.add({severity:'error',summary:(e as Error).message,life:5000});}finally{busy.value=false;}}
</script>
<template><div class="page-heading"><div><div class="eyebrow">NGƯỜI DÙNG NỀN TẢNG</div><h1>Khách hàng<span class="green-text">.</span></h1><p>Chăm sóc từng kết nối, xây dựng trải nghiệm tốt hơn.</p></div></div><section class="panel"><div class="filter-bar"><span class="search-input"><i class="pi pi-search"></i><InputText v-model="search" placeholder="Tìm tên khách hàng…" aria-label="Tìm khách hàng"/></span><span class="filter-count">Thông tin liên hệ được che theo quyền</span></div><QueryState :loading="loading" :error="error" @retry="refresh"/><DataTable v-if="data" :value="data.items" paginator :rows="12" class="grap-table"><template #empty><div class="table-empty">Không có khách hàng phù hợp.</div></template><Column header="KHÁCH HÀNG"><template #body="{data:d}"><div class="person-cell"><span class="avatar peach">{{initials(d.name)}}</span><div><strong>{{d.name}}</strong><small>{{d.phone}}</small></div></div></template></Column><Column header="THAM GIA"><template #body="{data:d}">{{date(d.createdAt,false)}}</template></Column><Column field="totalRides" header="TỔNG CHUYẾN"/><Column header="TRẠNG THÁI"><template #body="{data:d}"><StatusBadge :status="d.status"/></template></Column><Column><template #body="{data:d}"><Button v-if="['OperationsAdmin','SecurityAdmin'].includes(currentUser?.role??'')" :label="d.status==='ACTIVE'?'Hạn chế tài khoản':'Mở tài khoản'" :severity="d.status==='ACTIVE'?'danger':'success'" text size="small" @click="selected=d;show=true;reason=''"/></template></Column></DataTable></section><Dialog v-model:visible="show" modal :header="selected?.status==='ACTIVE'?'Hạn chế hoạt động tài khoản':'Mở lại tài khoản'" :style="{width:'460px'}"><p>Khách hàng: <strong>{{selected?.name}}</strong></p><p class="muted">Khóa tài khoản thu hồi các phiên đăng nhập. Chuyến đang chở vẫn giữ trạng thái để đội vận hành xử lý.</p><label>Lý do<Textarea v-model="reason" rows="4" class="full-width"/></label><template #footer><Button label="Quay lại" text severity="secondary" @click="show=false"/><Button label="Xác nhận" :loading="busy" :disabled="reason.trim().length<3" @click="restrict"/></template></Dialog></template>
